const source = $input.first().json;
if (source.approved !== true) throw new Error('Set approved to true after reviewing the input. No generation was started.');
if (typeof source.script !== 'string' || !source.script.trim() || source.script.length > 10000) throw new Error('Provide an approved narration script of 1 to 10000 characters.');
const request = {script: source.script.trim(), visualStyle: {type:'STOCK'}, aspectRatio: {width:16,height:9}, language: source.language || 'en', autoExport:true, remixActions:[{type:'ENABLE_CAPTIONS'}]};
return [{json: {request, pollDeadline: Date.now() + 15 * 60 * 1000}}];

const run = $input.first().json;
const expected = $('Start VideoGen workflow').first().json.workflowRunId;
if (typeof expected !== 'string' || !expected.startsWith('vg_work_')) throw new Error('Missing workflow run ID. Inspect the start execution before rerunning; a paid job may already exist.');
if (run.workflowRunId !== expected) throw new Error('Unexpected workflow run ID. Stopping without downloading.');
if (!['pending','running','succeeded','failed','cancelled'].includes(run.status)) throw new Error('Unexpected workflow status. Inspect the saved run ID before rerunning.');
if (run.status === 'failed' || run.status === 'cancelled') throw new Error('VideoGen run ' + expected + ' ended with status ' + run.status + '. Inspect that run before starting another paid job.');
if (run.status === 'succeeded') {
  if (typeof run.downloadUrl !== 'string' || !run.downloadUrl.startsWith('https://')) throw new Error('Export completed without a valid HTTPS download URL. Retrieve the existing run instead of starting a new generation.');
  return [{json: {...run, ready: true}}];
}
if (Date.now() >= $('Prepare request').first().json.pollDeadline) throw new Error('Polling timed out for ' + expected + '. The remote job may still be running. Retrieve this run before rerunning the workflow.');
return [{json: {...run, ready: false}}];
